script.text:
			/* <flatten type="Javascript"> */
const comboBoxTag = '_comboBox', loopkup_field = 'ma_ts', select_lookup_epx = '[nguon_ts] == 4', select_field = 'nguon_ts';
function load$GridDetail$(g) {
	g.add_commandEvent(on$GridDetail$ExecuteCommand);
	g._allowPaste = false; //Lỗi kxđ
	g.add_onRender(on$GridDetail$Render);
}
function on$GridDetail$Render(sender, eventArgs) {
	var g = eventArgs.grid;  
	initSelectGrid(g, select_field);
}

function dispose$GridDetail$(g) {
	try {g.remove_commandEvent(on$GridDetail$ExecuteCommand);} catch (ex) {}
	try {g.remove_onRender(on$GridDetail$Render);} catch (ex) {}
}
/* </flatten> */
function on$GridDetail$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, f = g.get_element().parentForm;
	switch (action) {
		case 'AfterMoveRow':
			moveSelectGrid(g, e.type.Value[0], e.type.Value[1], select_field); //from=[0] to=[1]
			break;
		case 'AfterCloneRow':
		case 'AfterInsertRow':
			createSelectGrid(g, g._activeRow, select_field);
			onChange$GridDetail$SelectField(g._getItem(g._activeRow, g._getColumnOrder(select_field));
			break;
		&Clipboard.Event.Before;
		&Clipboard.Event.Before.Request;
		&Clipboard.Event.Before.Process;
		&Clipboard.Event.After;
		&Clipboard.Event.After.Process;
		&GridExtraToolbarExecuteCommandScript;
		default:
			break;
	}
}

function initSelectGrid(g, field) {
	var c1 = g._getColumnOrder(loopkup_field);
	for (var i=1;i<=g._rowCount;i++) {
		var o = createSelectGrid(g,i,field);
		setIdleField(g, i, loopkup_field, select_lookup_epx);
	}
}

function createSelectGrid(g, n, field) {
	var c = g._getColumnOrder(field);
	var o = g._getItem(n, c);
	o.grid = g;
	o.row = n;
	o.hidden = true;
	var comboBox = document.createElement('select');
	var items = g._fields[c-1].Items;
	for(var i = 0;i<items.length;i++) {
		var option = document.createElement('option');
		option.value = items.[i][0]; option.innerText = items.[i][1];
		comboBox.add(option)
	}
	comboBox.id = o.id + comboBoxTag;
	comboBox.classList.add('FormComboBox','CellInput');
	comboBox.type='text';
	comboBox.onfocus = function (e) {g._focus(o); onSelectionOutlineEntry(this, true); };
	comboBox.onblur = function (e) {g._blur(o); onSelectionOutlineEntry(this, false); };
	comboBox.onchange = function (e) {g._setItemValue(n, c, this.value); o.onchange(); };	
	comboBox.selectedIndex = o.value - 1;
	comboBox.addEventListener('mousedown', function(e) {checkReadonlySelectGrid(g,e)});
	comboBox.addEventListener('keydown', function(e) {checkReadonlySelectGrid(g,e)});
	o.parentElement.appendChild(comboBox);
	return o;
}
function moveSelectGrid(g, from, to, field) {
	var c = g._getColumnOrder(field);
	from = g._getItem(from, c); to = g._getItem(to, c);
	document.getElementById(from.id + comboBoxTag).selectedIndex = from.value-1;
	document.getElementById(to.id + comboBoxTag).selectedIndex = to.value-1;
}
function checkReadonlySelectGrid(g, e) { 
	var f = g.get_element().parentForm;
	if (f._action == 'View') e.preventDefault();
}
function onChange$GridDetail$SelectField(o) {
	var g = o.grid, c1 = g._getColumnOrder(loopkup_field);
	g.setItemGridBehavior(o, [
		[loopkup_field, '', '', null]
	]); 	
	var valid = setIdleField(g, o.row, loopkup_field, select_lookup_epx);
	&SideProcess;
}
function setIdleField(g, row, field, boolExpression) {
	var c1 = g._getColumnOrder(field);
	var isTrue = g.calcExpression(row-1, boolExpression);
	g._getItem(row, c1)._idle = isTrue ? 9 : null;
	return isTrue
}


			&GridExtraToolbarScript;
